int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> f(n);
    for (int i = 0; i < n; i++) {
        cin >> f[i];
    }

    vector<vector<int>> adj(n);
    vector<vector<int>> radj(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        radj[b].push_back(a);
    }

    vector<int> order;
    vector<bool> visited(n, false);
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            stack<pair<int, int>> st;
            st.push({i, 0});
            visited[i] = true;
            while (!st.empty()) {
                auto& [u, idx] = st.top();
                if (idx < (int)adj[u].size()) {
                    int v = adj[u][idx];
                    idx++;
                    if (!visited[v]) {
                        visited[v] = true;
                        st.push({v, 0});
                    }
                } else {
                    order.push_back(u);
                    st.pop();
                }
            }
        }
    }

    reverse(order.begin(), order.end());

    vector<int> comp(n, -1);
    int comp_id = 0;
    for (int u : order) {
        if (comp[u] == -1) {
            stack<int> st;
            st.push(u);
            comp[u] = comp_id;
            while (!st.empty()) {
                int v = st.top();
                st.pop();
                for (int w : radj[v]) {
                    if (comp[w] == -1) {
                        comp[w] = comp_id;
                        st.push(w);
                    }
                }
            }
            comp_id++;
        }
    }

    vector<vector<int>> comp_adj(comp_id);
    for (int u = 0; u < n; u++) {
        for (int v : adj[u]) {
            if (comp[u] != comp[v]) {
                comp_adj[comp[u]].push_back(comp[v]);
            }
        }
    }

    for (int i = 0; i < comp_id; i++) {
        sort(comp_adj[i].begin(), comp_adj[i].end());
        auto last = unique(comp_adj[i].begin(), comp_adj[i].end());
        comp_adj[i].resize(last - comp_adj[i].begin());
    }

    vector<int> comp_has_assign(comp_id, 0);
    vector<int> comp_has_use(comp_id, 0);
    for (int i = 0; i < n; i++) {
        if (f[i] == 1) comp_has_assign[comp[i]] = 1;
        if (f[i] == 2) comp_has_use[comp[i]] = 1;
    }

    vector<int> reachable_assign(comp_id, 0);
    for (int i = 0; i < comp_id; i++) {
        if (comp_has_assign[i]) {
            reachable_assign[i] = 1;
        }
    }

    for (int i = 0; i < comp_id; i++) {
        for (int j : comp_adj[i]) {
            if (reachable_assign[i]) {
                reachable_assign[j] = 1;
            }
        }
    }

    vector<int> reachable_use(comp_id, 0);
    for (int i = 0; i < comp_id; i++) {
        if (comp_has_use[i]) {
            reachable_use[i] = 1;
        }
    }

    for (int i = comp_id - 1; i >= 0; i--) {
        for (int j : comp_adj[i]) {
            if (reachable_use[j]) {
                reachable_use[i] = 1;
            }
        }
    }

    vector<int> ans(n, 0);
    for (int i = 0; i < n; i++) {
        int c = comp[i];
        if (reachable_assign[c] && reachable_use[c]) {
            ans[i] = 1;
        }
    }

    for (int i = 0; i < n; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}
