#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> f(n + 1);
    for (int i = 1; i <= n; i++) cin >> f[i];

    vector<vector<int>> adj(n + 1), radj(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        radj[b].push_back(a);
    }

    vector<int> order;
    vector<int> state(n + 1, 0); // 0 unvisited,1 in stack,2 done
    vector<int> iter(n + 1, 0);
    stack<int> st;

    for (int i = 1; i <= n; i++) {
        if (state[i] == 0) {
            st.push(i);
            state[i] = 1;
            while (!st.empty()) {
                int u = st.top();
                if (iter[u] < (int)adj[u].size()) {
                    int v = adj[u][iter[u]++];
                    if (state[v] == 0) {
                        state[v] = 1;
                        st.push(v);
                    }
                } else {
                    order.push_back(u);
                    state[u] = 2;
                    st.pop();
                }
            }
        }
    }

    vector<int> comp(n + 1, -1);
    int cur = 0;
    for (int i = (int)order.size() - 1; i >= 0; i--) {
        int start = order[i];
        if (comp[start] != -1) continue;
        stack<int> s;
        s.push(start);
        comp[start] = cur;
        while (!s.empty()) {
            int u = s.top(); s.pop();
            for (int v : radj[u]) {
                if (comp[v] == -1) {
                    comp[v] = cur;
                    s.push(v);
                }
            }
        }
        cur++;
    }

    vector<bool> hasAssign(cur, false), hasUse(cur, false);
    for (int i = 1; i <= n; i++) {
        int c = comp[i];
        if (f[i] == 1) hasAssign[c] = true;
        else if (f[i] == 2) hasUse[c] = true;
    }

    vector<unordered_set<int>> condEdges(cur);
    for (int u = 1; u <= n; u++) {
        for (int v : adj[u]) {
            if (comp[u] != comp[v]) {
                condEdges[comp[u]].insert(comp[v]);
            }
        }
    }

    vector<bool> reachUse(cur, false);
    for (int c = 0; c < cur; c++) {
        if (hasUse[c]) reachUse[c] = true;
    }
    // BFS over condensation in reverse topological order (descending comp id)
    for (int c = cur - 1; c >= 0; c--) {
        for (int nb : condEdges[c]) {
            if (reachUse[nb]) {
                reachUse[c] = true;
                break;
            }
        }
    }

    vector<bool> reachAssign(cur, false);
    for (int c = 0; c < cur; c++) {
        if (hasAssign[c]) reachAssign[c] = true;
    }
    // BFS over condensation in topological order (ascending comp id)
    for (int c = 0; c < cur; c++) {
        if (reachAssign[c]) {
            for (int nb : condEdges[c]) {
                reachAssign[nb] = true;
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        int c = comp[i];
        bool ok = false;
        if (hasAssign[c] && hasUse[c]) {
            ok = true;
        } else if (hasAssign[c] && reachUse[c]) {
            ok = true;
        } else if (hasUse[c] && reachAssign[c]) {
            ok = true;
        }
        cout << (ok ? 1 : 0) << '\n';
    }

    return 0;
}
